const getPRNumberFromMergeGroup = (refName, logger) => {
    if (!refName) {
        return undefined;
    }
    // GITHUB_REF_NAME format for merge_group: pr-<number>-<sha>
    // e.g., "pr-123-abc123"
    const withoutPrefix = refName.replace(/^pr-/, "");
    const dashIndex = withoutPrefix.indexOf("-");
    if (dashIndex === -1) {
        logger.warning(`GITHUB_REF_NAME is not a valid merge_group format: ${refName}`);
        return undefined;
    }
    const prNumberStr = withoutPrefix.substring(0, dashIndex);
    const prNumber = parseInt(prNumberStr, 10);
    if (isNaN(prNumber)) {
        logger.warning(`Failed to parse PR number from GITHUB_REF_NAME: ${refName}`);
        return undefined;
    }
    return prNumber;
};
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const getPRNumberFromSHA = async (octokit, owner, repo, sha, logger) => {
    const maxRetries = 8;
    const retryIntervalMs = 5000;
    for (let attempt = 0; attempt <= maxRetries; attempt++) {
        try {
            const { data } = await octokit.rest.repos.listPullRequestsAssociatedWithCommit({
                owner,
                repo,
                commit_sha: sha,
            });
            if (data.length > 0) {
                return data[0].number;
            }
        }
        catch (error) {
            logger.warning(`Failed to get PR from SHA: ${error}`);
            return undefined;
        }
        if (attempt < maxRetries) {
            logger.info(`No PRs found for SHA ${sha}, retrying in ${retryIntervalMs / 1000}s (attempt ${attempt + 1}/${maxRetries})`);
            await sleep(retryIntervalMs);
        }
    }
    return undefined;
};
const getPRFiles = async (octokit, owner, repo, prNumber) => {
    const maxPerPage = 100;
    const maxFiles = 3000;
    const files = [];
    let page = 1;
    while (files.length < maxFiles) {
        const { data } = await octokit.rest.pulls.listFiles({
            owner,
            repo,
            pull_number: prNumber,
            per_page: maxPerPage,
            page,
        });
        if (data.length === 0) {
            break;
        }
        files.push(...data.map((f) => ({
            filename: f.filename,
            previous_filename: f.previous_filename,
        })));
        if (data.length < maxPerPage) {
            break;
        }
        page++;
        if (files.length >= maxFiles) {
            break;
        }
    }
    return files.slice(0, maxFiles);
};
