const list_targets_main = async () => {
    lib_core.exportVariable("AQUA_GLOBAL_CONFIG", aquaGlobalConfig);
    const executor = await NewExecutor({
        githubToken: input/* githubToken */.bU,
    });
    // Step 2: Run ci-info (skip for workflow_dispatch and schedule events)
    const eventName = github_context.eventName;
    const skipCiInfo = shouldSkipCiInfo(eventName);
    let pr = {};
    if (!skipCiInfo) {
        pr = await ci_info_main();
    }
    // Step 3: Check if commit is latest (for PR events)
    if (isPREvent(eventName)) {
        if (pr.pr) {
            const latestHeadSha = pr.pr.data.head.sha;
            const headSha = github_context.payload.pull_request?.head?.sha;
            validateHeadSha(headSha, latestHeadSha);
        }
    }
    // Step 4: Run list-targets-with-changed-files
    // The outputs (modules, targets) are set by listTargetsWithChangedFiles.main()
    await list_targets_with_changed_files_main(executor, pr);
};

;// CONCATENATED MODULE: ./src/actions/output-github-secrets/run.ts
const output_github_secrets_run_run = (inputs) => {
    if (!inputs.secretsConfig) {
        return { secrets: {} };
    }
    const githubSecrets = JSON.parse(inputs.githubSecrets);
    const secrets = {};
    for (const [envName, secretName] of Object.entries(inputs.secretsConfig)) {
        if (!(secretName in githubSecrets)) {
            throw new Error(`secret is not found: ${secretName}`);
        }
        secrets[envName] = githubSecrets[secretName];
    }
    return { secrets };
};

