const tfmigrate_main = async (secrets, githubTokenForGitHubProvider) => {
    const githubToken = input/* githubToken */.bU;
    const driftIssueNumber = env/* all */.Q7.TFACTION_DRIFT_ISSUE_NUMBER;
    const cfg = await getConfig();
    const targetConfig = await getTargetConfig({
        target: env/* all */.Q7.TFACTION_TARGET,
        workingDir: env/* all */.Q7.TFACTION_WORKING_DIR,
        isApply: true,
        jobType: getJobType(),
    }, cfg);
    const workingDir = external_path_.join(cfg.git_root_dir, targetConfig.working_directory);
    const driftIssueRepo = getDriftIssueRepo(cfg);
    const driftIssueRepoOwner = driftIssueRepo.owner;
    const driftIssueRepoName = driftIssueRepo.name;
    const ciInfoPrNumber = env/* all */.Q7.CI_INFO_PR_NUMBER;
    // Create a temporary file for apply output
    const tempDir = external_fs_.mkdtempSync(external_path_.join(external_os_.tmpdir(), "tfaction-"));
    const applyOutput = external_path_.join(tempDir, "apply_output.txt");
    const outputStream = external_fs_.createWriteStream(applyOutput);
    const executor = await NewExecutor({
        githubToken: githubToken,
        cwd: workingDir,
    });
    // Run tfmigrate apply with execAndComment (posts a comment on failure)
    let exitCode = 0;
    try {
        await executor
            .exec("tfmigrate", ["apply"], {
            cwd: workingDir,
            ignoreReturnCode: true,
            secretEnvs: secrets,
            group: "tfmigrate apply",
            env: {
                ...(env/* all */.Q7.TFMIGRATE_EXEC_PATH
                    ? { TFMIGRATE_EXEC_PATH: env/* all */.Q7.TFMIGRATE_EXEC_PATH }
                    : {}),
                ...(githubTokenForGitHubProvider
                    ? { GITHUB_TOKEN: githubTokenForGitHubProvider }
                    : {}),
            },
            listeners: {
                stdout: (data) => {
                    process.stdout.write(data);
                    outputStream.write(data);
                },
                stderr: (data) => {
                    process.stderr.write(data);
                    outputStream.write(data);
                },
            },
            comment: {
                token: githubToken,
                key: "tfmigrate-apply",
                pr: env/* all */.Q7.CI_INFO_PR_NUMBER,
                vars: {
                    tfaction_target: targetConfig.target,
                },
            },
        })
            .then((code) => {
            exitCode = code;
        });
    }
    finally {
        outputStream.end();
    }
    // If this is a drift issue, post the result to the drift issue
    if (driftIssueNumber) {
        const prUrl = `${github_context.serverUrl}/${github_context.repo.owner}/${github_context.repo.repo}/pull/${ciInfoPrNumber}`;
        try {
            await executor.exec("bash", ["-c", `cat ${applyOutput} && exit ${exitCode}`], {
                cwd: workingDir,
                ignoreReturnCode: true,
                comment: {
                    token: githubToken,
                    key: "drift-apply",
                    org: driftIssueRepoOwner,
                    repo: driftIssueRepoName,
                    pr: driftIssueNumber,
                    vars: {
                        pr_url: prUrl,
                        tfaction_target: targetConfig.target,
                    },
                },
            });
        }
        catch (error) {
            // Ignore the failure
            lib_core.warning(`Failed to post to drift issue: ${error}`);
        }
    }
    // Clean up temporary file
    try {
        external_fs_.rmdirSync(tempDir);
    }
    catch {
        // Ignore the failure
    }
    if (exitCode !== 0) {
        throw new Error("tfmigrate apply failed");
    }
};

