function mergeSecrets(secrets, awsSecrets) {
    const base = secrets
        ? JSON.parse(secrets)
        : undefined;
    const aws = awsSecrets
        ? JSON.parse(awsSecrets)
        : undefined;
    if (!base && !aws) {
        return undefined;
    }
    return { ...base, ...aws };
}

;// CONCATENATED MODULE: ./src/actions/apply/index.ts





const apply_main = async () => {
    const jobType = env/* all */.Q7.TFACTION_JOB_TYPE;
    const secrets = mergeSecrets(input/* secrets */.O3, input/* awsSecrets */.hf);
    const githubTokenForGitHubProvider = input/* githubTokenForGitHubProvider */.wN || undefined;
    if (jobType === "terraform") {
        await terraform_main(secrets, githubTokenForGitHubProvider);
    }
    else if (jobType === "tfmigrate") {
        await tfmigrate_main(secrets, githubTokenForGitHubProvider);
    }
};

;// CONCATENATED MODULE: ./src/actions/apply-label/run.ts


const FAIL_LABEL = "tfaction:apply-result:fail";
const FAIL_LABEL_COLOR = "d93f0b";
const apply_label_run_main = async (inputs) => {
    if (inputs.result === "skipped") {
        lib_core.info("Result is skipped, doing nothing");
        return;
    }
    const { owner, repo } = github_context.repo;
    const octokit = getOctokit(inputs.githubToken);
    const { data: currentLabels } = await octokit.rest.issues.listLabelsOnIssue({
        owner,
        repo,
        issue_number: inputs.prNumber,
    });
    const hasFailLabel = currentLabels.some((l) => l.name === FAIL_LABEL);
    if (inputs.result === "success") {
        if (hasFailLabel) {
            await octokit.rest.issues.removeLabel({
                owner,
                repo,
                issue_number: inputs.prNumber,
                name: FAIL_LABEL,
            });
            lib_core.info(`Removed label "${FAIL_LABEL}" from PR #${inputs.prNumber}`);
        }
        return;
    }
    // failure or cancelled
    if (!hasFailLabel) {
        const { data: addedLabels } = await octokit.rest.issues.addLabels({
            owner,
            repo,
            issue_number: inputs.prNumber,
            labels: [FAIL_LABEL],
        });
        lib_core.info(`Added label "${FAIL_LABEL}" to PR #${inputs.prNumber}`);
        const failLabel = addedLabels.find((l) => l.name === FAIL_LABEL);
        if (failLabel && failLabel.color !== FAIL_LABEL_COLOR) {
            await octokit.rest.issues.updateLabel({
                owner,
                repo,
                name: FAIL_LABEL,
                color: FAIL_LABEL_COLOR,
            });
            lib_core.info(`Updated label "${FAIL_LABEL}" color to #${FAIL_LABEL_COLOR}`);
        }
    }
};

