const conftest_run = async (inputs, config, targetConfig) => {
    const executor = inputs.executor;
    const workingDir = external_path_.join(config.git_root_dir, targetConfig.working_directory);
    const wdConfig = readTargetConfig(external_path_.join(workingDir, config.working_directory_file));
    const policies = buildPolicies(config, targetConfig, wdConfig, inputs.plan);
    if (policies.length !== 0) {
        await executor.exec("conftest", ["-v"], {
            cwd: workingDir,
            group: "conftest -v",
            comment: {
                token: inputs.githubToken,
                vars: {
                    tfaction_target: targetConfig.target,
                },
            },
        });
    }
    for (const policy of policies) {
        if (!policy.policy) {
            continue;
        }
        const paths = getConftestPaths(policy, workingDir, inputs.planJsonPath);
        const args = buildConftestArgs(policy, targetConfig.target, targetConfig.working_directory, paths);
        await executor.exec("conftest", args, {
            cwd: workingDir,
            group: "conftest",
            comment: {
                token: inputs.githubToken,
                key: "conftest",
                vars: {
                    tfaction_target: targetConfig.target,
                },
            },
        });
    }
};

