const validateProviders = (providerSelections, availableProviders) => {
    const allowedNames = new Set(availableProviders.map((p) => p.name));
    return Object.keys(providerSelections).filter((p) => !allowedNames.has(p));
};
const checkProviders = async (input) => {
    const args = input.terragruntRunAvailable
        ? ["run", "--", "version", "-json"]
        : ["version", "-json"];
    const result = await input.executor.getExecOutput(input.tfCommand, args, {
        cwd: input.workingDir,
        group: `${input.tfCommand} version -json`,
    });
    const versionInfo = JSON.parse(result.stdout);
    const providerSelections = versionInfo.provider_selections ?? {};
    const disallowed = validateProviders(providerSelections, input.availableProviders);
    if (disallowed.length === 0)
        return;
    if (input.prNumber > 0) {
        const octokit = getOctokit(input.githubToken);
        await post({
            octokit,
            prNumber: input.prNumber,
            templateKey: "disallowed-provider",
            vars: {
                tfaction_target: input.target,
                disallowed_providers: disallowed,
            },
        });
    }
    throw new Error(`Disallowed providers: ${disallowed.join(", ")}`);
};

